package com.example.bloodpressurerecord.domain.ocr

import com.example.bloodpressurerecord.domain.calculator.MeasurementInputRules
import com.example.bloodpressurerecord.domain.model.ReadingValue

/**
 * Calibrated recognizer for the fixed seven-digit layout of the supported LCD monitor.
 *
 * A reading is returned only when every digit is close to a labelled prototype and
 * sufficiently separated from the next digit class. Unknown displays fail closed.
 */
object CalibratedLcdRecognizer {

    fun recognize(image: BinaryImage): SegmentRecognition? {
        val matches = slots.indices.map { position ->
            match(position, pack(image, slots[position])) ?: return null
        }
        val digits = matches.map { it.digit }
        val systolic = digits[0] * 100 + digits[1] * 10 + digits[2]
        val diastolic = digits[3] * 10 + digits[4]
        val pulse = digits[5] * 10 + digits[6]
        val reading = ReadingValue(systolic, diastolic, pulse)
        if (MeasurementInputRules.validateReading(reading) != null) return null

        val confidence = matches.map { it.confidence }.average().toFloat()
        return SegmentRecognition(
            candidate = ReadingCandidate(
                systolic = systolic,
                diastolic = diastolic,
                pulse = pulse,
                flags = buildSet {
                    add(ReadingFlag.FROM_FALLBACK)
                    if (confidence < REVIEW_CONFIDENCE) add(ReadingFlag.AMBIGUOUS_DIGIT)
                }
            ),
            confidence = confidence
        )
    }

    private fun match(position: Int, sample: LongArray): Match? {
        val ranked = templates.asSequence()
            .filter { it.position == position }
            .groupBy { it.digit }
            .map { (digit, variants) ->
                digit to variants.minOf { hammingDistance(sample, it.words) }
            }
            .sortedBy { it.second }
        val best = ranked.firstOrNull() ?: return null
        val runnerUp = ranked.getOrNull(1)
        if (best.second > MAX_DISTANCE) return null
        if (runnerUp != null && runnerUp.second - best.second < MIN_CLASS_MARGIN) return null

        val shapeConfidence = 1f - best.second.toFloat() / FEATURE_BITS
        val marginConfidence = runnerUp?.let {
            ((it.second - best.second).toFloat() / 64f).coerceIn(0f, 1f)
        } ?: 1f
        return Match(best.first, shapeConfidence * 0.82f + marginConfidence * 0.18f)
    }

    private fun hammingDistance(first: LongArray, second: LongArray): Int =
        first.indices.sumOf { java.lang.Long.bitCount(first[it] xor second[it]) }

    private fun pack(image: BinaryImage, slot: Slot): LongArray {
        val words = LongArray(6)
        for (cellY in 0 until FEATURE_HEIGHT) {
            for (cellX in 0 until FEATURE_WIDTH) {
                val leftFraction = slot.left + slot.width * cellX / FEATURE_WIDTH
                val rightFraction = slot.left + slot.width * (cellX + 1) / FEATURE_WIDTH
                val topFraction = slot.top + slot.height * cellY / FEATURE_HEIGHT
                val bottomFraction = slot.top + slot.height * (cellY + 1) / FEATURE_HEIGHT
                val left = (image.width * leftFraction).toInt().coerceIn(0, image.width - 1)
                val right = (image.width * rightFraction).toInt().coerceIn(left + 1, image.width)
                val top = (image.height * topFraction).toInt().coerceIn(0, image.height - 1)
                val bottom = (image.height * bottomFraction).toInt().coerceIn(top + 1, image.height)

                var foreground = 0
                for (y in top until bottom) {
                    for (x in left until right) if (image[x, y]) foreground++
                }
                val density = foreground.toFloat() / ((right - left) * (bottom - top))
                if (density >= CELL_DENSITY) {
                    val bit = cellY * FEATURE_WIDTH + cellX
                    words[bit / Long.SIZE_BITS] =
                        words[bit / Long.SIZE_BITS] or (1L shl (bit % Long.SIZE_BITS))
                }
            }
        }
        return words
    }

    private data class Match(val digit: Int, val confidence: Float)
    private data class PackedTemplate(val position: Int, val digit: Int, val words: LongArray)
    private data class Slot(val left: Float, val top: Float, val right: Float, val bottom: Float) {
        val width: Float get() = right - left
        val height: Float get() = bottom - top
    }

    private const val FEATURE_WIDTH = 16
    private const val FEATURE_HEIGHT = 24
    private const val FEATURE_BITS = FEATURE_WIDTH * FEATURE_HEIGHT
    private const val CELL_DENSITY = 0.20f
    private const val MAX_DISTANCE = 46
    private const val MIN_CLASS_MARGIN = 12
    private const val REVIEW_CONFIDENCE = 0.90f

    private val slots = listOf(
        Slot(.36f, .14f, .51f, .42f),
        Slot(.50f, .14f, .75f, .42f),
        Slot(.73f, .14f, .99f, .42f),
        Slot(.48f, .40f, .75f, .70f),
        Slot(.72f, .40f, .99f, .70f),
        Slot(.59f, .70f, .79f, .99f),
        Slot(.76f, .70f, .99f, .99f)
    )

